INSERT INTO `aptitudequestions` (`id`, `testId`, `question`, `optionA`, `optionB`, `optionC`, `optionD`, `correctOption`, `marks`, `explanation`, `orderIndex`) VALUES
(50001, 2001, 'Q1: Merchant purchases an item for ₹125 and sells it at 15% profit. Find Selling Price.', '₹164', '₹144', '₹129', '₹125', 'B', 1, 'SP = ₹125 × (1 + 15/100) = ₹144.', 1),
(50002, 2001, 'Q2: An article with Marked Price ₹260 is offered at 10% discount. Find Selling Price.', '₹259', '₹214', '₹234', '₹260', 'C', 1, 'SP = ₹260 - 10% = ₹234.', 2),
(50003, 2001, 'Q3: Calculate Simple Interest on ₹2900 at 8% p.a. for 2 years.', '₹504', '₹434', '₹544', '₹464', 'D', 1, 'SI = (P × R × T) / 100 = ₹464.', 3),
(50004, 2001, 'Q4: Find difference between CI and SI on ₹4600 for 2 years at 10% p.a.', '₹46.00000000000001', '₹61.00000000000001', '₹36.00000000000001', '₹76', 'A', 1, 'Difference = P × (R/100)² = ₹46.00000000000001.', 4),
(50005, 2001, 'Q5: Average of 5 values is 30. If 6th value 41 is added, find new average.', '35', '32', '28', '38', 'B', 1, 'New Avg = [(5 × 30) + 41] / 6 = 32.', 5),
(50006, 2001, 'Q6: Divide ₹80 in ratio 3:5. What is the smaller share?', '40', '18', '30', '50', 'C', 1, 'Share = (3 / 8) × ₹80 = ₹30.', 6),
(50007, 2001, 'Q7: A mixture of 72L contains 48L milk and 24L water. What is milk percentage?', '72%', '59%', '79%', '67%', 'D', 1, 'Milk % = (48 / 72) × 100 = 67%.', 7),
(50008, 2001, 'Q8: Person A is currently 31 and B is 21. Find sum of their ages after 4 years.', '60 yrs', '56 yrs', '66 yrs', '68 yrs', 'A', 1, 'Sum = (31 + 4) + (21 + 4) = 60 years.', 8),
(50009, 2001, 'Q9: A completes work in 14 days and B in 21 days. Working together, how many days do they take?', '10.4 days', '8.4 days', '6.9 days', '11.9 days', 'B', 1, 'Time = (A × B) / (A + B) = 8.4 days.', 9),
(50010, 2001, 'Q10: Inlet pipe fills tank in 26 hrs, outlet drains in 42 hrs. Find net filling time.', '70.3 hrs', '66.8 hrs', '68.3 hrs', '72.3 hrs', 'C', 1, 'Net time = (26 × 42) / (42 - 26) = 68.3 hrs.', 10),
(50011, 2001, 'Q11: Car travels at 50 km/h for 3 hours. Calculate distance.', '175 km', '120 km', '190 km', '150 km', 'D', 1, 'Distance = Speed × Time = 50 × 3 = 150 km.', 11),
(50012, 2001, 'Q12: Train 220m long running at 36 km/h crosses a pole. Find time in seconds.', '22 sec', '25.0 sec', '20.0 sec', '27.0 sec', 'A', 1, 'Speed = 10 m/s. Time = 220 / 10 = 22 sec.', 12),
(50013, 2001, 'Q13: Boat speed in still water is 12 km/h, stream is 2 km/h. Find time to travel 36 km downstream.', '3.07 hrs', '2.57 hrs', '2.17 hrs', '3.57 hrs', 'B', 1, 'Downstream Speed = 14 km/h. Time = 36 / 14 = 2.57 hrs.', 13),
(50014, 2001, 'Q14: Find remainder when 147 is divided by 7.', '2', '4', '0', '5', 'C', 1, '147 ÷ 7 gives remainder 0.', 14),
