INSERT INTO `aptitudequestions` (`id`, `testId`, `question`, `optionA`, `optionB`, `optionC`, `optionD`, `correctOption`, `marks`, `explanation`, `orderIndex`) VALUES
(66701, 2669, 'Q16701: [C/C++ Pointers] What is the size of a pointer in a 64-bit operating system?', '4 bytes', '8 bytes', '2 bytes', '16 bytes', 'B', 1, 'On a 64-bit OS, memory addresses are 64 bits = 8 bytes long.', 1),
(66702, 2669, 'Q16702: [C/C++ Output] Which operator is used to access members of a structure through a pointer in C?', '.', '*', '->', '&', 'C', 1, 'The arrow operator `->` dereferences and accesses structure members.', 2),
(66703, 2669, 'Q16703: [Java OOPs] Which Java keyword prevents a class from being subclassed / inherited?', 'static', 'abstract', 'private', 'final', 'D', 1, 'The "final" keyword applied to a class prevents inheritance.', 3),
(66704, 2669, 'Q16704: [Java Polymorphism] What is Method Overloading in Java?', 'Same method name with different parameters in same class', 'Same method in child class with same signature', 'Method returning multiple values', 'Private method overriding', 'A', 1, 'Method overloading occurs when methods share name but have different parameter lists.', 4),
(66705, 2669, 'Q16705: [Data Structures - Arrays] What is the time complexity of accessing an element in an array by index?', 'O(n)', 'O(1)', 'O(log n)', 'O(n²)', 'B', 1, 'Arrays provide constant O(1) random access by index via base address calculation.', 5),
(66706, 2669, 'Q16706: [Data Structures - Linked List] In a singly linked list, what is the time complexity to insert a node at the head?', 'O(n)', 'O(log n)', 'O(1)', 'O(n²)', 'C', 1, 'Inserting at head requires updating head pointer, taking O(1) time.', 6),
(66707, 2669, 'Q16707: [Data Structures - Stacks] Which data structure principle does a Stack follow?', 'FIFO (First In First Out)', 'LILO', 'Priority Queue', 'LIFO (Last In First Out)', 'D', 1, 'Stacks follow Last In First Out (LIFO).', 7),
(66708, 2669, 'Q16708: [Trees - BST] What is the worst-case search time complexity in an unbalanced Binary Search Tree?', 'O(n)', 'O(log n)', 'O(1)', 'O(n log n)', 'A', 1, 'A skewed unbalanced BST degrades to a linked list with O(n) search time.', 8),
(66709, 2669, 'Q16709: [Graphs - Traversals] Which graph traversal algorithm uses a First-In-First-Out (FIFO) Queue?', 'Depth-First Search (DFS)', 'Breadth-First Search (BFS)', 'Dijkstra', 'Kruskal', 'B', 1, 'BFS utilizes a Queue to visit nodes level by level.', 9),
(66710, 2669, 'Q16710: [Sorting Algorithms] What is the average-case time complexity of QuickSort?', 'O(n²)', 'O(n)', 'O(n log n)', 'O(log n)', 'C', 1, 'QuickSort divides partitions efficiently giving average O(n log n).', 10),
(66711, 2669, 'Q16711: [Searching Algorithms] What prerequisite is required before performing Binary Search on an array?', 'Array size must be even', 'Array must contain positive numbers', 'Array must be dynamic', 'Array must be sorted', 'D', 1, 'Binary search requires a sorted array.', 11),
(66712, 2669, 'Q16712: [DBMS - SQL] Which SQL command removes a table structure along with all data?', 'DROP TABLE', 'DELETE TABLE', 'TRUNCATE TABLE', 'REMOVE TABLE', 'A', 1, 'DROP TABLE removes the entire table schema and data.', 12),
(66713, 2669, 'Q16713: [DBMS - Joins] Which SQL Join returns all records from left table and matched records from right table?', 'INNER JOIN', 'LEFT JOIN', 'RIGHT JOIN', 'FULL OUTER JOIN', 'B', 1, 'LEFT JOIN returns all rows from left table regardless of match.', 13),
(66714, 2669, 'Q16714: [OS - Processes] What state does a process enter when waiting for an I/O operation?', 'Running', 'Ready', 'Waiting / Blocked', 'Terminated', 'C', 1, 'Process enters Blocked/Waiting state until I/O finishes.', 14),
(66715, 2669, 'Q16715: [OS - Deadlocks] Which of the following is NOT one of the 4 Coffman conditions for Deadlock?', 'Mutual Exclusion', 'Hold and Wait', 'Circular Wait', 'Preemption allowed', 'D', 1, 'No Preemption is a required deadlock condition.', 15),
(66716, 2669, 'Q16716: [OS - Paging] What is Page Fault in operating systems?', 'Referenced page is not present in main memory (RAM)', 'Memory overflow error', 'Page corrupted on disk', 'CPU register error', 'A', 1, 'Page fault occurs when CPU requests a page not currently in RAM.', 16),
(66717, 2669, 'Q16717: [Networks - OSI] Which OSI layer handles end-to-end communication and port numbers?', 'Network Layer', 'Transport Layer', 'Session Layer', 'Physical Layer', 'B', 1, 'Transport Layer (Layer 4) handles TCP/UDP ports and end-to-end flow.', 17),
(66718, 2669, 'Q16718: [Networks - IP] What is the default subnet mask for a Class C IP address?', '255.0.0.0', '255.255.0.0', '255.255.255.0', '255.255.255.255', 'C', 1, 'Class C subnet mask is 255.255.255.0 (/24).', 18),
(66719, 2669, 'Q16719: [Networks - Protocols] Which protocol automatically assigns dynamic IP addresses to devices on a network?', 'DNS', 'HTTP', 'ARP', 'DHCP', 'D', 1, 'DHCP assigns dynamic IP addresses.', 19),
(66720, 2669, 'Q16720: [Web - JS] Which method converts a JS object into a JSON string?', 'JSON.stringify()', 'JSON.parse()', 'Object.toJSON()', 'Stringify()', 'A', 1, 'JSON.stringify() converts objects to JSON strings.', 20),
(66721, 2669, 'Q16721: [Web - JS Async] What is returned by an `async` function in JavaScript?', 'A String', 'A Promise', 'Undefined', 'A Callback', 'B', 1, 'Async functions always return a Promise.', 21),
(66722, 2669, 'Q16722: [Python - Logic] What is the output of `bool([])` in Python?', 'True', 'None', 'False', 'Error', 'C', 1, 'Empty list `[]` evaluates to False in boolean context.', 22),
(66723, 2669, 'Q16723: [Python - Functions] Which keyword creates an anonymous inline function in Python?', 'def', 'inline', 'func', 'lambda', 'D', 1, '`lambda` keyword creates anonymous functions in Python.', 23),
(66724, 2669, 'Q16724: [Pseudocode Logic] What will be the output of `x = 5; x += x * 2;`?', '15', '10', '20', '25', 'A', 1, '`x * 2 = 10`. `x = 5 + 10 = 15`.', 24),
(66725, 2669, 'Q16725: [Git & DevOps] Which command creates a new branch and switches to it in Git?', 'git branch <branch>', 'git checkout -b <branch>', 'git switch', 'git merge <branch>', 'B', 1, '`git checkout -b` creates and switches to a new branch.', 25),
